"use strict";(globalThis.webpackChunkdocs=globalThis.webpackChunkdocs||[]).push([[872],{4069(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>o,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"Learning/Management/Project Management","title":"Project Management","description":"Understand Project Management","source":"@site/docs/Learning/Management/Project Management.md","sourceDirName":"Learning/Management","slug":"/Learning/Management/Project Management","permalink":"/notes/docs/Learning/Management/Project Management","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/Learning/Management/Project Management.md","tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"Presentation Skills","permalink":"/notes/docs/Learning/Management/Presentation"},"next":{"title":"Creative Work Tax Relief","permalink":"/notes/docs/Learning/Others/Polish Labour Law/creativework"}}');var a=n(4848),i=n(8453);const o={},r="Project Management",l={},c=[{value:"Understand Project Management",id:"understand-project-management",level:2},{value:"Establish Project Scope",id:"establish-project-scope",level:2},{value:"Develop A Schedule And Budget",id:"develop-a-schedule-and-budget",level:2},{value:"Assemble Your Team",id:"assemble-your-team",level:2},{value:"Manage Project Risks",id:"manage-project-risks",level:2},{value:"Monitor Progress and Problems",id:"monitor-progress-and-problems",level:2},{value:"Stakeholder Management",id:"stakeholder-management",level:2},{value:"Close-Out",id:"close-out",level:2}];function d(e){const t={em:"em",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"project-management",children:"Project Management"})}),"\n",(0,a.jsx)(t.h2,{id:"understand-project-management",children:"Understand Project Management"}),"\n",(0,a.jsx)(t.p,{children:"A project is a set of interrelated activities, involving a group of people who are working together toward a common goal over a period of time."}),"\n",(0,a.jsx)(t.p,{children:"Project management is the planning, scheduling, and orchestrating of project activities to achieve objectives within a specified period of time."}),"\n",(0,a.jsx)(t.p,{children:"Build trust with your team members. Acknowledge difficult situations, empathize with team members, admit you don't have all the answers, and ask team members for help. Listen to everyone's opinions. Explain all decisions. Lead by example."}),"\n",(0,a.jsx)(t.p,{children:"Project management can be understood as a four-step process: Planning, Buildup, Implementation, and Phase-out. Activities can overlap between phases. Sometimes project management is linear, but sometimes it is adaptive (iterative)."}),"\n",(0,a.jsx)(t.p,{children:"Adaptive project management is about performing experiments quickly, striving for early delivery, staff projects with people who have a talent for adapting, and avoid over-relying on metrics (assuming predictability)."}),"\n",(0,a.jsx)(t.p,{children:"The enemy of innovation is not failure, but prolonged expensive failure. Experiments require discipline, and to be inexpensive. Identify uncertainties, rate them, list the highest rated unknowns, and start by testing them in order."}),"\n",(0,a.jsx)(t.h2,{id:"establish-project-scope",children:"Establish Project Scope"}),"\n",(0,a.jsxs)(t.p,{children:["Start by defining problems, not solutions. Then brainstorm alternatives, evaluate them, and choose the best one. Listen to the client's ",(0,a.jsx)(t.em,{children:"real"})," needs."]}),"\n",(0,a.jsx)(t.p,{children:"Identify your stakeholders. Anyone who has a vested interest in the outcome of the project."}),"\n",(0,a.jsx)(t.p,{children:"Define SMART objectives for the project. Specific, Measurable, Achievable, Relevant, Time-bound."}),"\n",(0,a.jsx)(t.p,{children:"Anticipate trade-offs in quality (scope), time, cost. Those three are competing demands. Find out which variable matters the most, and be transparent about compromises."}),"\n",(0,a.jsx)(t.p,{children:"Beware of scope creep. Get agreement on scope ahead of time. Either list what's in or out of scope, or establish scope-tolerance parameters (or ranges, aka non-functional requirements). Get signoff on scope."}),"\n",(0,a.jsx)(t.p,{children:"Once you know the scope, estimate project resources. Break the scope in Major tasks, then Minor tasks, then individual tasks. This division is called Work Breakdown Structure (WBS). Estimate tasks in terms of dollars and person-hours (the mythical man-month, haha). Consider skills you will need to complete the tasks. Don't worry about these estimates not being precise. As a rule of thumb, multiply your estimates by 1.5x (also known as padding)."}),"\n",(0,a.jsx)(t.p,{children:"Create a project charter containing: mission statement, roles and responsibilities, sponsors, scope and objectives, relationship between project's goals and higher organizational goals, expected time frame and milestones, resources available to the team, constraints, assumptions, quality requirements, and major risks."}),"\n",(0,a.jsx)(t.h2,{id:"develop-a-schedule-and-budget",children:"Develop A Schedule And Budget"}),"\n",(0,a.jsx)(t.p,{children:"To get a schedule, start by the deadline. Then work backwards, mapping interim deliverables. Identify bottlenecks and elaborate ways to address them. Establish a control and comm channel (governance?) system for updating the schedule."}),"\n",(0,a.jsx)(t.p,{children:"Seek ways to make the roadmap more precise: spot errors, oversights, overcommitments, and bottlenecks. There are many tools to help with these, like Gantt charts, PERT (performance evaluation and review technique) charts, and Critical Path Diagrams (flowchart). Use these tools flexibly."}),"\n",(0,a.jsx)(t.p,{children:"A budget is a financial blueprint that details measurable expenses and expected returns over a time frame. Even though the budget needs to be estimated at the beginning, it needs to be adjusted throughout the project. Typical expenses include people, travel, training, supplies, space, etc. Costs like insurance, licensing, and legal are often overlooked. For that reason, it's important to secure a contingency fund. Use the budget to decide if the project is even worth pursuing."}),"\n",(0,a.jsx)(t.h2,{id:"assemble-your-team",children:"Assemble Your Team"}),"\n",(0,a.jsx)(t.p,{children:"PM's responsibilities: identify resources, recruit team, coordinate activities, negotiate with sponsors, mediate conflicts, set milestones, manage the budget. Ultimately, keep the work on track. It's more important to empower team members, than directing them."}),"\n",(0,a.jsx)(t.p,{children:"The project can also have a team lead (TM). Their responsibilities include regularly communicating progress and projects to the PM, periodically assessing team progress and team's outlook, and making sure everyone's voice is heard. They play six roles: Initiator (encourage team to work), Role Model, Negotiator, Listener, Coach, and the usual Work."}),"\n",(0,a.jsx)(t.p,{children:"A team member's responsibilities are to complete tasks on time, communicate concerns, support other team members, and ask for help when needed."}),"\n",(0,a.jsx)(t.p,{children:"To assemble an affective team, one must identify required skills and find individuals who possess those skills (or train people). Assign people to tasks based on their abilities: Technical, Problem-Solving, Interpersonal, Organizational, Developmental, and Communication. Teams cannot be too friendly, too inflexible, or have internal conflicts."}),"\n",(0,a.jsx)(t.h2,{id:"manage-project-risks",children:"Manage Project Risks"}),"\n",(0,a.jsx)(t.p,{children:"Risk management is identifying key risks and developing plans for preventing them or mitigating their adverse effects. It consists of three steps: conducting a risk audit, taking action to minimize risks, and develop contingency plans."}),"\n",(0,a.jsx)(t.p,{children:"A risk audit needs ideas to be collector widely, and includes internal and external risks. Map risks according to their likelihood and harm. Start with the most likely and harmful ones."}),"\n",(0,a.jsx)(t.p,{children:'A contingency plan deals with a potential problem. "If [...] happens, how could we respond in a way that would minimize the damage?"'}),"\n",(0,a.jsx)(t.h2,{id:"monitor-progress-and-problems",children:"Monitor Progress and Problems"}),"\n",(0,a.jsx)(t.p,{children:"KEep track of decisions, assignments, action items. Document meetings. Every milestone should include successful testing, and should be celebrated."}),"\n",(0,a.jsx)(t.p,{children:"Track the major three components of change. Make sure, every week, we are:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"strengthening and enforcing the vision of where we're going"}),"\n",(0,a.jsx)(t.li,{children:"helping people understand why they have to change"}),"\n",(0,a.jsx)(t.li,{children:"helping people know what's the next step"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Some common issues are: focus on the wrong tasks, poor work quality, and burnout."}),"\n",(0,a.jsx)(t.p,{children:"Don't forget to monitor the budget, the schedule, the scope, the quality. Don't let control become micromanagement. Emphasize timely responses."}),"\n",(0,a.jsx)(t.h2,{id:"stakeholder-management",children:"Stakeholder Management"}),"\n",(0,a.jsx)(t.p,{children:"Have face-to-face project launch meetings, it motivates the team. USe it to align roles and responsibilities, review the project charter, seek understanding of the project, outline the available resources and incentives."}),"\n",(0,a.jsx)(t.p,{children:"Schedule regular weekly team meetings."}),"\n",(0,a.jsx)(t.p,{children:"File progress reports regularly. Hold project update meetings regularly."}),"\n",(0,a.jsx)(t.h2,{id:"close-out",children:"Close-Out"}),"\n",(0,a.jsx)(t.p,{children:"Hold a post-project evaluation. Evaluate the quality, schedule, and cost."}),"\n",(0,a.jsx)(t.p,{children:"Do a project (blameless) post-mortem to review lessons learned. Review assumptions, estimates, productivity of meetings, what we would do differently."}),"\n",(0,a.jsx)(t.p,{children:"Draft a final project report, containing the current status, future status, ongoing critical work, risks, handovers for other projects, and limitations."}),"\n",(0,a.jsx)(t.p,{children:"Celebrate regardless of success."})]})}function h(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var s=n(6540);const a={},i=s.createContext(a);function o(e){const t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);